{
  "description": "The creature is a horse-shaped quadruped shown in right-facing profile standing on a small patch of grass and dirt. It has the overall body shape, head, legs, hooves, and long hairy tail of a horse, colored in shades of brown with lighter tan fur on the belly, but most of its dorsal and lateral surfaces are covered in dense, overlapping, rounded brown scales. The scales cover the forehead, the top and sides of the neck where a mane would be, the entire back, sides, rump, and the upper portions of all four legs, while the face, lower legs, underside, and tail remain as horse hair and skin. The animal stands with all four legs on the ground against a plain off-white background, rendered in a detailed naturalistic illustration style.",
  "parts": [
    {
      "part": "head",
      "looks_like": "a brown horse head in right profile with a dark brown muzzle, black nostril, dark eye with eyelid, light whiskers on the chin and muzzle, and a slightly open mouth showing the lower lip",
      "where": "at the front right end of the body, attached to the neck"
    },
    {
      "part": "ears",
      "looks_like": "two upright, pointed horse ears with brown outer hair and darker inner fur, triangular in shape",
      "where": "on top of the head, one behind the other, above the scaled forehead"
    },
    {
      "part": "mane",
      "looks_like": "no hair mane is visible; instead the mane area is covered by overlapping large rounded scales that continue from the forehead down the dorsal neck",
      "where": "along the top of the neck from behind the ears to the shoulders"
    },
    {
      "part": "legs",
      "looks_like": "four thick, sturdy horse legs with brown hair on the lower half and overlapping brown scales on the upper half, with visible joints and fetlocks",
      "where": "underneath the torso, two forelegs at the front and two hind legs at the rear, in a standing position"
    },
    {
      "part": "feet",
      "looks_like": "four rounded, solid dark brown hooves with a slightly lighter sole edge",
      "where": "at the bottom tip of each leg, resting on the ground"
    },
    {
      "part": "tail",
      "looks_like": "a long, straight horse tail made of coarse, straight brown hair hanging vertically",
      "where": "at the rear of the body, attached to the rump, extending down to near the hocks"
    },
    {
      "part": "scales",
      "looks_like": "overlapping keratinous, rounded pangolin-like scales, each brown with a darker brown base and a lighter tan-brown edge, arranged in neat diagonal rows",
      "where": "covering the forehead cap, the entire neck, back, sides, rump, and upper portions of all four legs"
    },
    {
      "part": "plates",
      "looks_like": "same as scales - large, flat, overlapping armor plates with a smooth, slightly ridged surface",
      "where": "continuous covering over the torso, neck, and upper limbs as described"
    },
    {
      "part": "markings",
      "looks_like": "light cream-tan furry undercoat contrasting with the dark brown lower legs and scaled upper body",
      "where": "on the underside of the belly, chest, and inner sides of the legs"
    }
  ],
  "attached_objects": [],
  "animals": [
    "horse",
    "pangolin"
  ],
  "separate_bodies": 1,
  "heads": 1,
  "walking_legs": 4,
  "wings": 0,
  "extra_limb_pieces": 0,
  "tails": 1
}
